queries.sql:
SELECT b.briefing_date,b.status,jsonb_object_keys(b.metadata) AS metadata_key
FROM public.sports_daily_briefings b WHERE b.briefing_date>='2026-10-07'
ORDER BY b.briefing_date DESC,metadata_key;

SELECT status_code,timed_out,count(*) AS responses,min(created) AS first_at,max(created) AS last_at
FROM net._http_response WHERE created >= CURRENT_TIMESTAMP-INTERVAL '6 hours'
GROUP BY status_code,timed_out ORDER BY status_code,timed_out;
